import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("yes")
        return

    n = int(data[0])

    if n <= 1:
        print("yes")
        return

    arr = list(map(int, data[1:n+1]))

    # Check if alternating between increasing and decreasing
    # Pattern: should be increasing, then decreasing, then increasing, etc.
    expected_increase = True  # First pair should be increasing

    for i in range(len(arr) - 1):
        if expected_increase:
            if arr[i] >= arr[i + 1]:
                print("no")
                return
        else:
            if arr[i] <= arr[i + 1]:
                print("no")
                return
        expected_increase = not expected_increase

    print("yes")

if __name__ == "__main__":
    main()
